(() => {
'use strict';
const $=s=>document.querySelector(s),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const project=MediaInfoKurzprojekte.find(x=>x.id===new URLSearchParams(location.search).get('thema'));
if(!project){$('#projectApp').innerHTML='<section class="paper"><h1>Wählen Sie ein Projekt.</h1><p>Dieser Link gehört zu keinem der vier kurzen Projekte.</p><a class="a-button" href="woche44.html#auswahl">Zur Auswahl →</a></section>';return;}
const id=project.id,SCHEMA='mediainfolab-kurzprojekt',PREFIX='mediainfolab_kurzprojekte_v1:';
let owner='',state={fields:{},checks:[],completed:false},storeOK=true,photo=null;
const required=[],allowed=new Set(),qualityById={
 nachrichten:['Ich habe bei allen drei Nachrichten eine Entscheidung getroffen.','Ich habe jeweils eine konkrete Textstelle und meinen nächsten Schritt aufgeschrieben.','Ich habe meine Antworten mit den Lösungshinweisen verglichen und bei Bedarf verbessert.'],
 bildausschnitt:['Meine beiden Ausschnitte zeigen deutlich unterschiedliche Teile desselben Bildes.','Jeder Ausschnitt hat eine eigene passende Überschrift.','Ich erkläre bei beiden Ausschnitten, was fehlt und welchen Eindruck das auslösen kann.','Meine Antwort unterscheidet Sichtbares von Vermutungen.'],
 plakat:['Mein Plakat enthält alle sechs Angaben aus dem Auftrag.','Titel, Zeitpunkt und Ort sind schnell zu finden und gut lesbar.','Ich habe drei Änderungen mit ihrem Nutzen erklärt.','Ich habe meinen Entwurf anhand der Selbstkontrolle geprüft.'],
 storyboard:['Meine sechs Szenen zeigen einen Anfang, eine Schwierigkeit und ein Ende.','Bei jeder Szene steht, was sichtbar geschieht.','Ich habe passende Bildausschnitte gewählt und mindestens zwei begründet.','Die Geschichte ist ohne gesprochene Erklärung nachvollziehbar.']
};
function identity(){try{return String(JSON.parse(localStorage.getItem('mediainfolab_student_access_v1')||'null')?.email||'').toLowerCase();}catch{return '';}}
function load(){owner=identity();try{const raw=JSON.parse(localStorage.getItem(PREFIX+owner+':'+id)||'null');state=raw&&raw.fields?clean(raw):{fields:{},checks:[],completed:false};}catch{state={fields:{},checks:[],completed:false};storeOK=false;}}
function clean(raw){const fields={};for(const [k,v] of Object.entries(raw?.fields||{})){if(!/^[a-zA-Z][a-zA-Z0-9]{0,50}$/.test(k)||typeof v!=='string')continue;if(/^crop[AB](zoom|x|y)$/.test(k)){const zoom=k.endsWith('zoom');const n=Number(v);fields[k]=String(Number.isFinite(n)?Math.max(zoom?100:0,Math.min(zoom?300:100,n)):(zoom?100:50));}else fields[k]=v.slice(0,12000);}return {fields,checks:(Array.isArray(raw.checks)?raw.checks:[]).filter(x=>Number.isInteger(x)&&x>=0&&x<qualityById[id].length),completed:raw.completed===true,updatedAt:typeof raw.updatedAt==='string'?raw.updatedAt:''};}
function save(){state.updatedAt=new Date().toISOString();try{if(!owner)throw Error();localStorage.setItem(PREFIX+owner+':'+id,JSON.stringify(state));storeOK=true;}catch{storeOK=false;}status();}
function status(){const el=$('#saveState');if(el){el.textContent=storeOK?'In diesem Browser gespeichert. Für OneDrive: «Arbeitsstand herunterladen».':'Speichern im Browser ist nicht möglich. Laden Sie jetzt Ihren Arbeitsstand herunter und sichern Sie regelmässig.';el.classList.toggle('warning',!storeOK);}const done=$('#doneState');if(done)done.textContent=state.completed?'Grundauftrag als fertig markiert':'Grundauftrag noch nicht abgeschlossen';const bar=$('#qualityProgress');if(bar)bar.style.width=Math.round(state.checks.length/qualityById[id].length*100)+'%';}
function field(key,label,hint='',type='textarea',must=true,options=[]){allowed.add(key);if(must&&!required.includes(key))required.push(key);const val=state.fields[key]||'';let control=type==='select'?`<select id="f-${key}" data-field="${key}"><option value="">Bitte auswählen</option>${options.map(o=>`<option value="${e(o)}" ${val===o?'selected':''}>${e(o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="f-${key}" data-field="${key}" maxlength="3000" ${must?'aria-required="true"':''}>${e(val)}</textarea>`:`<input id="f-${key}" data-field="${key}" maxlength="180" type="text" value="${e(val)}" ${must?'aria-required="true"':''}>`;return `<label class="workfield" for="f-${key}"><span>${label}${!must&&key!=='closing'?' <small>(freiwilliger Zusatz)</small>':''}</span>${hint?`<small>${hint}</small>`:''}${control}</label>`;}
const help=(q,a)=>`<details class="helpbox"><summary>${q}</summary><p>${a}</p></details>`;
const section=(n,title,html)=>`<section class="paper projectstep" id="schritt${n}"><div class="steptitle"><span class="stepbadge">${n}</span><h2>${title}</h2></div>${html}</section>`;
const messages=[
 {tag:'A · SMS · Paket',context:'Sie haben nichts bestellt und erwarten kein Paket.',from:'Angezeigter Absender: Paketservice',body:'Ihr Paket konnte nicht zugestellt werden. Zahlen Sie die offene Gebühr von CHF 2.90 bis heute 18 Uhr, sonst geht die Sendung zurück.\nZahlung: paketservice-zahlung.example',answer:'Nicht über diese Nachricht reagieren. Sie erwarten kein Paket. Die Nachricht fordert eine Zahlung über einen Link und setzt Sie unter Zeitdruck. Das sind konkrete Warnzeichen. Falls Sie doch eine Sendung vermuten, prüfen Sie diese in der selbst geöffneten offiziellen App oder Webseite. Keine Karten- oder Kontodaten über den SMS-Link eingeben.'},
 {tag:'B · Mitteilung · Konto',context:'Sie haben vor einer Minute selbst auf der offiziellen Webseite einer Lernplattform ein neues Passwort angefordert.',from:'Angezeigter Absender: Lernplattform',body:'Sie haben soeben eine Änderung Ihres Passworts angefordert. Wenn Sie das waren, schliessen Sie den Vorgang in Ihrem bereits geöffneten Browserfenster ab. Falls Sie das nicht waren, prüfen Sie Ihr Konto über die Ihnen bekannte Webseite.',answer:'Die Mitteilung passt zu der Handlung, die Sie selbst ausgelöst haben. Sie fordert weder eine Zahlung noch eine Antwort mit Ihrem Passwort. Sie können im bereits geöffneten offiziellen Browserfenster fortfahren. Die zeitliche Übereinstimmung und der passende Inhalt sprechen für die Mitteilung; ein Absendername allein beweist ihre Echtheit trotzdem nicht.'},
 {tag:'C · Direktnachricht · Gewinn',context:'Sie haben an keinem Wettbewerb teilgenommen.',from:'Angezeigter Absender: City Festival',body:'Glückwunsch! Sie haben zwei Festivalpässe gewonnen. Senden Sie zur Bestätigung ein Foto Ihrer Identitätskarte und den Code, der gleich per SMS kommt. Sie haben dafür noch 10 Minuten.',answer:'Nicht antworten und nichts senden. Sie haben nicht teilgenommen. Die Nachricht verlangt ein Ausweisfoto und einen SMS-Code und macht Zeitdruck. Ein Code kann einen Kontozugriff oder eine Zahlung bestätigen. Melden Sie den Kontakt über die Plattform und blockieren Sie ihn. Für Rückfragen suchen Sie den Veranstalter selbst über einen bekannten offiziellen Kanal.'},
 {tag:'D · E-Mail · Auffälliger Link',context:'Sie erwarten eine Rechnung. Die E-Mail ist fehlerfrei geschrieben und verwendet ein bekanntes Firmenlogo.',from:'Angezeigter Absender: Kundenservice',body:'Ihre Rechnung ist verfügbar. Melden Sie sich hier mit Ihrem bestehenden Passwort an: kundenkonto.example.sicher-pruefen.example',answer:'Erst unabhängig überprüfen. Gute Sprache, Logo und die erwartete Rechnung reichen nicht als Nachweis. Der lange Link kann einen vertrauten Namen nur vortäuschen. Öffnen Sie die bekannte offizielle Adresse selbst und suchen Sie die Rechnung dort. Entscheidend ist der wirkliche Zielort, nicht ein bekannter Begriff irgendwo im Link.'},
 {tag:'E · Chat · Bekannte Person',context:'Die Nachricht erscheint im Konto einer Person, die Sie kennen.',from:'Angezeigter Absender: Eine bekannte Person',body:'Kannst du mir kurz helfen? Ich habe mich ausgesperrt. Gleich kommt bei dir ein Code an. Schick ihn mir bitte sofort weiter, dann komme ich wieder rein.',answer:'Den Code nicht weitergeben. Auch ein bekanntes Konto kann übernommen worden sein. Fragen Sie die Person über einen anderen bereits bekannten Kontaktweg, etwa die gespeicherte Telefonnummer. Der Code auf Ihrem Gerät kann zu Ihrem eigenen Konto gehören. Ein vertrauter Name ersetzt diese Prüfung nicht.'}
];
function messageCard(m,i,extra=false){return `<article class="message"><p class="kicker">${m.tag}</p><p><strong>Die Situation:</strong> ${m.context}</p><small>${m.from}</small><blockquote>${e(m.body)}</blockquote>${field('m'+i+'decision','1. Was würden Sie tun?','','select',!extra,['Nicht reagieren: nichts anklicken oder senden','Zuerst unabhängig überprüfen','Im selbst geöffneten offiziellen Dienst fortfahren'])}${field('m'+i+'clue','2. Welche Information ist für Ihre Entscheidung wichtig?','Nennen Sie eine Stelle aus der Nachricht oder eine Angabe zur Situation. Schreiben Sie dazu, weshalb sie wichtig ist.','textarea',!extra)}${field('m'+i+'action','3. Was tun Sie als Nächstes?','Schreiben Sie eine konkrete Handlung. «Vorsichtig sein» allein ist noch keine Handlung.','textarea',!extra)}<button class="a-button outline small" type="button" data-feedback="${i}">Meine Antwort mit Hinweisen vergleichen</button><div class="feedback" id="feedback${i}" hidden aria-live="polite"></div></article>`;}
function news(){return section(1,'Zuerst ein Beispiel lesen',`<p>Sie prüfen drei erfundene Nachrichten. Die Beispiele sind ungefährlich; die angezeigten Adressen sind keine Links. Sie müssen keine echten Nachrichten oder persönlichen Daten öffnen.</p><ol><li>Lesen Sie zuerst die Situation und dann die Nachricht.</li><li>Füllen Sie die drei Felder darunter aus.</li><li>Öffnen Sie die Lösungshinweise. Vergleichen und verbessern Sie Ihre Antwort.</li></ol><div class="example"><strong>Beispiel für eine genaue Begründung</strong><p>Zu allgemein: «Das sieht komisch aus.»<br>Genauer: «Die Nachricht verlangt mein Passwort. Ich schicke es nicht. Ich öffne die bekannte Webseite selbst und prüfe dort mein Konto.»</p></div>${help('Muss ich sicher wissen, ob eine Nachricht echt ist?','Nein. Wenn die Angaben nicht ausreichen, ist «zuerst unabhängig überprüfen» eine sinnvolle Entscheidung. Beschreiben Sie, wie Sie überprüfen, ohne den fraglichen Link zu benutzen.')}`)+section(2,'Die drei Nachrichten bearbeiten',messages.slice(0,3).map((m,i)=>messageCard(m,i)).join(''))+section(3,'Ihre Antworten überprüfen',`<p>Lesen Sie Ihre drei Antworten. Steht bei jeder Nachricht eine konkrete Information und eine konkrete nächste Handlung? Verbessern Sie ungenaue Stellen.</p><p><strong>Merken Sie sich:</strong> Ein Logo oder Absendername ist kein Echtheitsbeweis. Prüfen Sie zweifelhafte Nachrichten über einen selbst geöffneten, bekannten offiziellen Kanal. Geben Sie keine Passwörter, Kartenangaben oder Bestätigungscodes über verdächtige Nachrichten weiter.</p><p class="source-note">Fachliche Grundlage: <a href="https://www.bacs.admin.ch/de/phishing-de" target="_blank" rel="noopener">Bundesamt für Cybersicherheit: Phishing</a>. Die Fälle und Lösungshinweise wurden für diesen Auftrag erstellt.</p>`);}
function range(key,label,min,max,defaultVal){allowed.add(key);const v=state.fields[key]??String(defaultVal);return `<div class="cropcontrol"><label for="f-${key}">${label} <output id="out-${key}">${e(v)}</output></label><input id="f-${key}" data-field="${key}" type="range" min="${min}" max="${max}" value="${e(v)}"></div>`;}
function cropCard(letter){const a=letter==='A';return `<article><h3>Ausschnitt ${letter}</h3><canvas width="800" height="600" class="cropview" id="crop${letter}" role="img" aria-label="Ihr verstellbarer Bildausschnitt ${letter}"></canvas><div class="controls">${range('crop'+letter+'zoom','Vergrösserung',100,300,a?220:100)}${range('crop'+letter+'x','Nach links oder rechts verschieben',0,100,a?4:100)}${range('crop'+letter+'y','Nach oben oder unten verschieben',0,100,a?60:50)}<button type="button" class="a-button small outline" data-crop-download="${letter}">Ausschnitt als Bild herunterladen</button></div>${field('headline'+letter,'Überschrift für Ausschnitt '+letter,'Schreiben Sie höchstens einen kurzen Satz. Welche Aussage soll dieser Ausschnitt vermitteln?','text')}${field('effect'+letter,'Was zeigt dieser Ausschnitt – und was fehlt?','Nennen Sie mindestens ein sichtbares und ein weggelassenes Detail. Erklären Sie in 2–3 Sätzen, welchen Eindruck eine Person bekommen könnte, die nur diesen Ausschnitt sieht.')}</article>`;}
function crops(){return section(1,'Das ganze Bild ansehen',`<p>Eine Gruppe sammelt in einem Park Abfall. Das folgende Bild wurde mit KI als Übungsmaterial erstellt; es zeigt kein dokumentiertes Ereignis. Ihre Aufgabe: Zeigen Sie, wie zwei Ausschnitte derselben Szene einen unterschiedlichen Eindruck erzeugen.</p><img class="imagefull" src="assets/parkbild.jpg" alt="Vier junge Erwachsene mit Handschuhen, Abfallsäcken und Greifzangen sammeln Abfall in einem Park. Links greift eine Person nach einem Becher neben einer Bank."><p class="source-note">KI-generiertes Übungsbild · keine echten Personen oder Berichterstattung</p><div class="example"><strong>So kann ein Ausschnitt wirken</strong><p>Ein enger Ausschnitt zeigt einen Becher und eine Hand. Die Sammelsäcke und die anderen Helfenden fehlen. Man weiss dadurch weniger über die Situation. Aus einem einzelnen Bild lässt sich nicht sicher erkennen, ob ein Gegenstand gerade aufgehoben oder hingelegt wird.</p></div>`)+section(2,'Zwei unterschiedliche Ausschnitte gestalten',`<p>Verstellen Sie die Regler unter den Bildern. Bei grösserer Vergrösserung sehen Sie einen kleineren Teil des Fotos. Mit den anderen Reglern verschieben Sie den Ausschnitt. Die Vorschläge sind nur ein Startpunkt: Ändern Sie mindestens einen Ausschnitt bewusst.</p><ol><li>Zeigen Sie in Ausschnitt A nur einen kleinen Teil der Szene.</li><li>Zeigen Sie in Ausschnitt B weitere Informationen, die bei A fehlen.</li><li>Schreiben Sie zu beiden Ausschnitten eine Überschrift und die Erklärung.</li></ol><div class="two">${cropCard('A')}${cropCard('B')}</div>${help('Wie könnte eine Überschrift lauten?','Eine sachliche Überschrift nennt, was sichtbar ist. Eine zugespitzte Überschrift kann einen stärkeren Eindruck erzeugen. Wenn Sie bewusst zuspitzen, erklären Sie unten, welche Vermutung dadurch entstehen könnte. Behaupten Sie keine sichere Handlung, die das Einzelbild nicht beweist.')}`)+section(3,'Sichtbares und Vermutungen unterscheiden',field('difference','Was kann man anhand des ganzen Bildes sagen – und was bleibt unsicher?','Schreiben Sie 2–3 Sätze. Beginnen Sie zum Beispiel mit «Man sieht …» und «Aus dem Bild allein weiss man nicht …».')+`<details class="helpbox"><summary>Vergleichshilfe nach Ihrer eigenen Antwort öffnen</summary><p>Man sieht mehrere Personen mit Handschuhen, Greifzangen und Säcken. Das passt zur beschriebenen Sammelaktion. Ein enger Ausschnitt kann diese Hinweise ausblenden. Das Foto allein zeigt keinen Bewegungsablauf und beweist nicht, wer den Abfall ursprünglich hinterlassen hat. Unterschiedliche begründete Antworten sind möglich.</p></details>`);}
const posterFacts='<ul><li>Anlass: Kleidertausch</li><li>Datum: Samstag, 21. November 2026</li><li>Zeit: 14–17 Uhr</li><li>Ort: Jugendtreff Nord</li><li>Mitbringen: höchstens fünf saubere Kleidungsstücke</li><li>Kosten: Eintritt frei</li></ul>';
function posterMarkup(){const f=state.fields;const colors={'Blau':'#164e99','Grün':'#14614f','Violett':'#62418a'};return `<div class="poster ${f.align==='Zentriert'?'postercenter':''}" style="--accent:${colors[f.palette]||colors.Blau}"><div class="postertag">Fiktiver Übungsanlass</div><h3>${e(f.posterTitle||'Ihr Titel')}</h3><div class="posterwhen">${e(f.posterWhen||'Datum und Zeit')}</div><p><strong>${e(f.posterWhere||'Ort')}</strong></p><p>${e(f.posterBring||'Was soll man mitbringen?')}</p><p><strong>${e(f.posterCost||'Kosten')}</strong></p></div>`;}
function poster(){return section(1,'Den Aushang untersuchen',`<p>Dieser Aushang ist absichtlich unübersichtlich. Es geht um einen <strong>erfundenen</strong> Anlass. Sie sollen keine neuen Angaben erfinden, sondern die vorhandenen Angaben verständlicher darstellen.</p><div class="two"><div class="frozen"><p class="messytitle">Samstag 21. November 2026</p><div class="huge">HÖCHSTENS FÜNF<br>saubere Kleidungsstücke</div><p class="tiny">Kleidertausch · Eintritt frei</p><p style="text-align:center">Jugendtreff Nord</p><p style="text-align:right">14–17 Uhr</p></div><div><h3>Diese sechs Angaben müssen bleiben</h3>${posterFacts}</div></div>${field('posterProblem','Was würden Sie an diesem Aushang verbessern?','Nennen Sie zwei konkrete Probleme. Beispiel: «Die mitzubringenden Sachen sind auffälliger als der Anlass.»')}`)+section(2,'Einen klaren Entwurf erstellen',`<p>Füllen Sie die fünf Inhaltsfelder aus. Datum und Zeit stehen zusammen in einem Feld. Rechts sehen Sie sofort Ihren Entwurf. Wählen Sie anschliessend eine Farbe und die Ausrichtung. Die Vorlage gibt Ihnen eine gut lesbare Schrift und Grössenabstufungen vor.</p><div class="two"><div>${field('posterTitle','Titel: Wie heisst der Anlass?','Der Titel soll als Erstes auffallen.','text')}${field('posterWhen','Datum und Uhrzeit','Übernehmen Sie beide Angaben vollständig.','text')}${field('posterWhere','Ort','','text')}${field('posterBring','Was soll man mitbringen?','Die Mengenbegrenzung und «sauber» müssen erhalten bleiben.','text')}${field('posterCost','Kosten','','text')}${field('palette','Akzentfarbe','','select',true,['Blau','Grün','Violett'])}${field('align','Ausrichtung','','select',true,['Linksbündig','Zentriert'])}</div><div><h3>Ihre Live-Vorschau</h3><div id="posterPreview">${posterMarkup()}</div><p class="muted">Die Vorlage hilft bei der Gestaltung. Entscheidend sind Ihre Auswahl und Ihre Begründung.</p></div></div>`)+section(3,'Prüfen und drei Änderungen erklären',`<p>Schauen Sie Ihren Entwurf fünf Sekunden lang an. Decken Sie ihn dann kurz mit der Hand ab: Konnten Sie Anlass, Datum und Ort schnell finden? Vergleichen Sie danach alle sechs Angaben mit der Liste in Schritt 1.</p>${field('posterReason','Welche drei Änderungen helfen beim Lesen?','Schreiben Sie drei kurze Sätze. Nennen Sie jeweils die Änderung und ihren Nutzen. Beispiel: «Der Anlass steht oben in grosser Schrift. So erkennt man sofort, worum es geht.»')}<details class="helpbox"><summary>Vergleichshilfe nach Ihrer eigenen Antwort öffnen</summary><p>Ein klarer Titel zeigt den Anlass. Datum und Zeit gehören zusammen. Der Ort braucht einen eigenen gut erkennbaren Platz. Ähnliche Angaben stehen beieinander. Wenige Farben und genügend Abstand erleichtern die Orientierung. Es gibt mehrere gute Lösungen; nicht alle Plakate müssen gleich aussehen.</p></details>`);}
const sceneNames=['Die Ausgangslage','Die Schwierigkeit','Der erste Versuch','Die neue Idee','Die Handlung','Das sichtbare Ergebnis'];
function cameraSVG(choice){if(choice==='Detail')return '<svg viewBox="0 0 200 100" aria-hidden="true"><rect x="15" y="10" width="170" height="80" rx="6"/><rect x="70" y="25" width="60" height="50" rx="5"/><path d="M25 20h15M25 20v15M175 80h-15M175 80V65"/></svg>';if(choice==='Nah')return '<svg viewBox="0 0 200 100" aria-hidden="true"><rect x="15" y="10" width="170" height="80" rx="6"/><circle cx="100" cy="42" r="17"/><path d="M65 88q0-30 35-30t35 30"/></svg>';return '<svg viewBox="0 0 200 100" aria-hidden="true"><rect x="15" y="10" width="170" height="80" rx="6"/><circle cx="95" cy="38" r="9"/><path d="M95 47v23m0-15-17 9m17-9 17 9M95 70l-12 16m12-16 12 16M25 75h42m60 0h48"/></svg>';}
function storyboard(){return section(1,'Eine kleine Geschichte wählen',`<p>Sie planen einen kurzen Film <strong>ohne gesprochene Worte</strong>. Heute wird nichts gefilmt und niemand muss mitspielen. Ein Plan aus sechs beschriebenen Bildern genügt. Man nennt diesen Plan <strong>Storyboard</strong>.</p><p>Wählen Sie eine Idee: den Schlüssel suchen, ein Getränk vor dem Umkippen retten, einen verpassten Bus bemerken oder eine eigene harmlose Alltagssituation.</p>${field('storyIdea','Meine Geschichte in einem Satz','Zum Beispiel: «Eine Person sucht den Schlüssel, der die ganze Zeit am Rucksack hängt.»','text')}<div class="example"><strong>Sichtbar beschreiben</strong><p>Schwer zu filmen: «Die Person ist gestresst.»<br>Sichtbar: «Die Person schaut auf die Uhr und durchsucht schnell beide Jackentaschen.»</p></div><div class="notice"><strong>Drei mögliche Bildausschnitte:</strong> «Übersicht» zeigt die Person und die Umgebung. «Nah» zeigt zum Beispiel Gesicht und Oberkörper. «Detail» zeigt einen kleinen wichtigen Teil, etwa eine Hand, einen Schlüssel oder ein Display.</div>`)+section(2,'Die sechs Szenen planen',`<p>Füllen Sie jede Karte aus. Schreiben Sie jeweils 1–2 Sätze: <strong>Was sieht man und was passiert?</strong> Wählen Sie den Bildausschnitt. Sie dürfen die vorgeschlagenen Funktionen der Szenen an Ihre Geschichte anpassen; ein Anfang, eine Schwierigkeit und ein nachvollziehbares Ende müssen erkennbar bleiben.</p><div class="two">${sceneNames.map((s,i)=>`<article class="storyframe"><h3>${i+1} · ${s}</h3><div class="storyicon" id="sceneIcon${i}">${cameraSVG(state.fields['scene'+i+'camera'])}</div>${field('scene'+i+'text','Was sieht man in Szene '+(i+1)+'?','Beschreiben Sie eine sichtbare Handlung. Keine gesprochenen Sätze nötig.')}${field('scene'+i+'camera','Welcher Bildausschnitt passt?','','select',true,['Übersicht','Nah','Detail'])}</article>`).join('')}</div>${field('cameraReason','Begründen Sie zwei Ihrer Bildausschnitte.','Nennen Sie die Szenennummer und erklären Sie, warum gerade dieser Ausschnitt hilft. Beispiel: «Szene 3 als Detail: Man erkennt den Schlüssel an der falschen Stelle.»')}`)+section(3,'Den Film im Kopf ansehen',`<p>Lesen Sie nur Ihre sechs Szenen, ohne den Satz aus Schritt 1. Können Sie die Geschichte so verstehen? Ist die Lösung am Ende sichtbar? Ergänzen Sie eine fehlende Handlung oder ein wichtiges Detail.</p>${field('storyFix','Was haben Sie beim Prüfen geändert?','Beschreiben Sie Ihre Verbesserung. Wenn Sie nichts ändern mussten, nennen Sie die sichtbaren Handlungen, die das Ende verständlich machen.')}<details class="helpbox"><summary>Ein vollständiges Vergleichsbeispiel ansehen</summary><ol><li>Übersicht: Eine Person steht mit Rucksack vor einer geschlossenen Haustür.</li><li>Detail: Die Hand greift in die leere Jackentasche.</li><li>Nah: Die Person durchsucht auch die zweite Tasche und schaut suchend zur Tür.</li><li>Detail: Am Rucksackriemen hängt ein Schlüssel.</li><li>Nah: Die Person sieht den Schlüssel und nimmt ihn ab.</li><li>Detail: Der Schlüssel dreht sich im Schloss; die Tür öffnet sich.</li></ol><p>Das Ende wird durch die geöffnete Tür sichtbar. Ihre Geschichte darf anders aufgebaut sein. Kopieren Sie nicht einfach das Beispiel.</p></details>`);}
function extras(){let body='';if(id==='nachrichten')body='<p>Prüfen Sie die zwei schwierigeren Fälle genauso wie die ersten drei. Begründen Sie besonders, weshalb ein professionelles Aussehen oder eine bekannte Person allein nicht genügt.</p>'+messages.slice(3).map((m,i)=>messageCard(m,i+3,true)).join('');if(id==='bildausschnitt')body='<p>Erstellen Sie eine sachliche Version: Verwenden Sie das ganze Bild und schreiben Sie eine Überschrift, die nicht mehr behauptet, als die Übungssituation und das Bild hergeben.</p>'+field('extraHeadline','Meine sachliche Überschrift','','text',false)+field('extraWhy','Warum ist diese Version vollständiger?','Vergleichen Sie mit Ihrem engeren Ausschnitt. Nennen Sie zwei Informationen, die nun sichtbar sind.','textarea',false);if(id==='plakat')body='<p>Entwickeln Sie eine zweite Variante. Laden Sie zuerst Ihren bisherigen Arbeitsstand herunter, damit die erste Version erhalten bleibt. Stellen Sie dann Farbe oder Ausrichtung um. Prüfen Sie beide Varianten und entscheiden Sie sich begründet für eine.</p>'+field('extraCompare','Meine erste und meine zweite Variante','Notieren Sie die beiden Einstellungen. Beschreiben Sie, welche Version Sie wählen und weshalb sie für diesen Aushang besser passt.','textarea',false);if(id==='storyboard')body='<p>Erfinden Sie einen anderen Schluss. Die ersten vier Szenen bleiben gleich. Ändern Sie nur Szene 5 und 6. Beschreiben Sie, welchen anderen Eindruck dieses Ende vermittelt.</p>'+field('extraScene5','Alternative Szene 5','','textarea',false)+field('extraScene6','Alternative Szene 6','','textarea',false)+field('extraEffect','Wie verändert sich die Geschichte?','','textarea',false);return `<section class="paper"><p class="kicker">Wenn Sie weiterarbeiten möchten · 15–20 Min.</p><h2>Zusatzauftrag</h2><details><summary>Zusatzauftrag öffnen</summary>${body}</details><p class="muted">Sie dürfen stattdessen auch einen anderen Grundauftrag wählen. Sichern Sie zuerst Ihr bisheriges Ergebnis.</p></section>`;}
function finish(){return `<section class="paper" id="abschluss"><p class="kicker">Prüfen und sichern · 5 Minuten</p><h2>Ist Ihr Grundauftrag fertig?</h2><p>Setzen Sie ein Häkchen nur, wenn die Aussage für Ihr Ergebnis stimmt. Die Seite prüft, ob die nötigen Felder ausgefüllt sind; die inhaltliche Qualität prüfen Sie selbst.</p><div class="progressline"><span id="qualityProgress"></span></div>${qualityById[id].map((t,i)=>`<label class="checkrow"><input type="checkbox" data-quality="${i}" ${state.checks.includes(i)?'checked':''}><span>${t}</span></label>`).join('')}<p><button class="a-button" type="button" id="complete">Grundauftrag als fertig markieren</button></p><p id="completeMessage" role="status" aria-live="polite"></p><p class="drafttag" id="doneState"></p>${field('closing','Mein Abschluss für heute','Was ist fertig? Was wäre Ihr nächster konkreter Schritt? Bei einem fertigen Auftrag: Was haben Sie gelernt?','textarea',false)}<ol><li><strong>Arbeitsstand herunterladen:</strong> Speichern Sie die JSON-Datei in OneDrive → Informatik → Projekte. Sie enthält Ihre Eingaben und Einstellungen. Falls Ihr Browser sie automatisch in «Downloads» ablegt, verschieben Sie sie von dort in den Projektordner.</li><li><strong>Ergebnis als PDF:</strong> Im Druckfenster «Als PDF speichern» oder «Microsoft Print to PDF» wählen. Speichern Sie die PDF im gleichen Ordner. Auch ein Zwischenstand lässt sich ausgeben.</li><li><strong>Später weiterarbeiten:</strong> Öffnen Sie dieses Projekt, verwenden Sie dieselbe Schulmail und klicken Sie auf «Sicherung laden». Wählen Sie Ihre JSON-Datei. Diese Datei öffnen Sie über «Sicherung laden», nicht durch einen Doppelklick. Die PDF ist zum Lesen und Zeigen; die JSON-Datei ist zum Weiterarbeiten.</li></ol><p><button class="a-button" data-export type="button">Arbeitsstand herunterladen</button> <button class="a-button outline" data-print type="button">Ergebnis als PDF</button></p><p class="muted">Das Speichern in diesem Browser sendet nichts an die Lehrperson. Während andere Prüfung schreiben, müssen Sie Ihr Ergebnis nicht vorzeigen.</p><a href="woche44.html#auswahl">Zur Auswahl zurück →</a></section>`;}
function render(){required.length=0;allowed.clear();document.title=project.title+' · MedienInfoLab';$('#projectApp').innerHTML=`<header class="projecthero"><p class="kicker">Projekt ${project.number} · ${project.subtitle}</p><h1>${project.title}</h1><p class="lead">${project.product}</p><div class="meta"><span>${project.duration} Grundauftrag</span><span>Allein · ohne Ton</span><span>Zusatzauftrag vorhanden</span></div></header><div class="actionbar"><a href="#schritt1">Zum ersten Schritt ↓</a><button class="a-button small outline" data-export type="button">Arbeitsstand herunterladen</button><button class="a-button small outline" data-import type="button">Sicherung laden</button><button class="a-button small" data-print type="button">Ergebnis als PDF</button></div><p class="savestatus" id="saveState" role="status"></p><div class="notice"><strong>Sie arbeiten direkt auf dieser Seite.</strong> Lesen Sie jeweils einen Schritt und füllen Sie die Felder aus. Sie brauchen kein weiteres Programm. Bei wenig Zeit dürfen Sie einen Zwischenstand sichern. Sie müssen heute nicht alle Projekte lösen.</div>${({nachrichten:news,bildausschnitt:crops,plakat:poster,storyboard})[id]()}${finish()}${extras()}<input type="file" id="loadFile" accept=".json,application/json" hidden><div class="printout" id="printout"></div>`;status();if(id==='bildausschnitt')loadPhoto();}
function loadPhoto(){if(photo){drawCrops();return;}photo=new Image();photo.onload=drawCrops;photo.onerror=()=>{const n=document.createElement('p');n.className='notice warning';n.textContent='Das Bild konnte nicht geladen werden. Laden Sie die Seite erneut. Ihre Texte bleiben im Browser erhalten.';$('#schritt2').prepend(n);};photo.src='assets/parkbild.jpg';}
function drawCrops(){if(!photo?.naturalWidth)return;for(const letter of ['A','B']){const canvas=$('#crop'+letter);if(!canvas)continue;const zoom=Number(state.fields['crop'+letter+'zoom']??(letter==='A'?220:100))/100;const x=Number(state.fields['crop'+letter+'x']??(letter==='A'?4:100))/100,y=Number(state.fields['crop'+letter+'y']??(letter==='A'?60:50))/100;const sw=Math.min(photo.width,photo.height*4/3)/zoom,sh=sw*3/4;const ctx=canvas.getContext('2d');ctx.drawImage(photo,(photo.width-sw)*x,(photo.height-sh)*y,sw,sh,0,0,800,600);}}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportState(){save();download('Projekt '+project.subtitle+' Arbeitsstand.json',JSON.stringify({schema:SCHEMA,version:1,project:id,owner,state},null,2));}
function results(){const f=state.fields;const para=(label,key)=>`<h3>${label}</h3><p class="answertext">${e(f[key]||'Noch nicht bearbeitet')}</p>`;let out='';if(id==='nachrichten')out=messages.map((m,i)=>({m,i})).filter(({m,i})=>i<3||f['m'+i+'decision']||f['m'+i+'clue']||f['m'+i+'action']).map(({m,i})=>`<section><h2>${m.tag}</h2><p>${m.context}</p><blockquote>${e(m.body).replaceAll('\n','<br>')}</blockquote>${para('Meine Entscheidung','m'+i+'decision')}${para('Meine Begründung','m'+i+'clue')}${para('Mein nächster Schritt','m'+i+'action')}</section>`).join('');if(id==='bildausschnitt'){out='<p>KI-generiertes Übungsbild: eine Sammelaktion im Park.</p><img src="assets/parkbild.jpg" alt="Gesamtes Übungsbild"><div class="two">'+['A','B'].map(l=>`<section><h2>Ausschnitt ${l}</h2><img src="${$('#crop'+l).toDataURL('image/jpeg',.9)}" alt="Ausschnitt ${l}">${para('Meine Überschrift','headline'+l)}${para('Wirkung und fehlende Informationen','effect'+l)}</section>`).join('')+'</div>'+para('Sichtbares und Vermutungen','difference')+(f.extraHeadline?para('Sachliche Überschrift','extraHeadline')+para('Begründung','extraWhy'):'');}if(id==='plakat')out=para('Probleme am ursprünglichen Plakat','posterProblem')+posterMarkup()+para('Meine drei begründeten Änderungen','posterReason')+(f.extraCompare?para('Vergleich zweier Varianten','extraCompare'):'');if(id==='storyboard')out=para('Meine Geschichte','storyIdea')+'<table class="printtable"><thead><tr><th>Szene</th><th>Sichtbare Handlung</th><th>Ausschnitt</th></tr></thead><tbody>'+sceneNames.map((s,i)=>`<tr><td>${i+1} · ${s}</td><td class="answertext">${e(f['scene'+i+'text']||'Noch offen')}</td><td>${e(f['scene'+i+'camera']||'Noch offen')}</td></tr>`).join('')+'</tbody></table>'+para('Zwei Bildausschnitte begründet','cameraReason')+para('Meine Überprüfung','storyFix')+(f.extraScene5||f.extraScene6?para('Alternatives Ende: Szene 5','extraScene5')+para('Alternatives Ende: Szene 6','extraScene6')+para('Wirkung','extraEffect'):'');return `<div class="printresult"><p>MedienInfoLab · Projekt ${project.number}</p><h1>${project.title}</h1><p>${e(owner)} · ${new Date().toLocaleDateString('de-CH')}</p><p><strong>${state.completed?'Grundauftrag selbst als fertig geprüft':'Zwischenstand'}</strong></p>${out}<h2>Mein Abschluss für heute</h2><p class="answertext">${e(f.closing||'Noch keine Abschlussnotiz eingetragen.')}</p></div>`;}
load();render();
document.addEventListener('input',event=>{const el=event.target,k=el.dataset.field;if(!k||!allowed.has(k))return;state.fields[k]=el.value;if(k!=='closing'&&!k.startsWith('extra')){state.completed=false;state.checks=[];document.querySelectorAll('[data-quality]').forEach(c=>c.checked=false);}save();if(el.type==='range'){const o=$('#out-'+k);if(o)o.textContent=el.value;drawCrops();}if(id==='plakat')$('#posterPreview').innerHTML=posterMarkup();if(id==='storyboard'&&k.endsWith('camera'))$('#sceneIcon'+k.match(/\d/)[0]).innerHTML=cameraSVG(el.value);});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.quality!==undefined){const i=Number(el.dataset.quality);state.checks=state.checks.filter(x=>x!==i);if(el.checked)state.checks.push(i);state.completed=false;save();}});
document.addEventListener('click',event=>{const el=event.target.closest('button');if(!el)return;if(el.hasAttribute('data-export'))exportState();if(el.hasAttribute('data-import'))$('#loadFile').click();if(el.hasAttribute('data-print')){if(id==='bildausschnitt'&&!photo?.naturalWidth){$('#saveState').textContent='Bitte warten Sie, bis das Bild geladen ist.';return;}$('#printout').innerHTML=results();document.body.classList.add('printing');window.print();}if(el.dataset.cropDownload){const l=el.dataset.cropDownload;if(!photo?.naturalWidth)return;const a=document.createElement('a');a.href=$('#crop'+l).toDataURL('image/jpeg',.92);a.download='Bildausschnitt '+l+'.jpg';a.click();}if(el.dataset.feedback!==undefined){const i=Number(el.dataset.feedback),box=$('#feedback'+i);const missing=['decision','clue','action'].some(k=>!state.fields['m'+i+k]?.trim());box.hidden=false;box.innerHTML=missing?'<p>Füllen Sie zuerst die drei Felder zu dieser Nachricht aus. Danach können Sie Ihre Antwort mit den Hinweisen vergleichen.</p>':`<strong>Hinweise zum Vergleichen</strong><p>${messages[i].answer}</p><p>Ihre Formulierung darf anders sein. Prüfen Sie Ihre Begründung und verbessern Sie sie, wenn etwas fehlt.</p>`;}if(el.id==='complete'){const missing=required.filter(k=>!state.fields[k]?.trim());const sameCrop=id==='bildausschnitt'&&['zoom','x','y'].every(k=>$('#f-cropA'+k).value===$('#f-cropB'+k).value);const msg=$('#completeMessage');if(missing.length){msg.textContent=`Noch ${missing.length} benötigte Felder sind leer. Ergänzen Sie sie oder sichern Sie Ihren Zwischenstand.`;$('#f-'+missing[0]).focus();}else if(sameCrop){msg.textContent='Ihre Ausschnitte sind noch gleich eingestellt. Verändern Sie einen Ausschnitt so, dass er andere Informationen zeigt.';}else if(state.checks.length!==qualityById[id].length){msg.textContent='Prüfen Sie zuerst alle Aussagen über dem Knopf und setzen Sie die passenden Häkchen.';}else{state.completed=true;save();msg.textContent='Ihr Grundauftrag ist als fertig markiert. Laden Sie nun die Sicherung und Ihr Ergebnis herunter. Danach können Sie vertiefen oder ein anderes Projekt wählen.';}}});
document.addEventListener('change',async event=>{if(event.target.id!=='loadFile')return;const file=event.target.files?.[0];if(!file)return;try{if(file.size>300000)throw Error('Diese Datei ist zu gross. Wählen Sie eine Arbeitsstandsdatei dieses Projekts.');const raw=JSON.parse(await file.text());if(raw.schema!==SCHEMA||raw.version!==1||raw.project!==id)throw Error('Diese Sicherung gehört nicht zu diesem Projekt. Öffnen Sie zuerst das passende Projekt.');if(raw.owner!==owner)throw Error('Diese Sicherung gehört zu einer anderen Schulmail. Wechseln Sie zuerst zur passenden Schulmail.');if(!raw.state||typeof raw.state.fields!=='object'||Array.isArray(raw.state.fields))throw Error('Die Sicherung ist nicht vollständig.');if(!confirm('Die Sicherung ersetzt die Eingaben dieses Projekts in diesem Browser. Haben Sie Ihren jetzigen Stand bei Bedarf heruntergeladen?'))return;state=clean(raw.state);state.completed=false;save();render();$('#saveState').textContent='Sicherung geladen. Prüfen Sie Ihre Eingaben; der Abschluss kann erneut markiert werden.';}catch(err){$('#saveState').textContent=err.message||'Die Datei kann nicht gelesen werden.';}finally{event.target.value='';}});
window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
$('#fontToggle').addEventListener('click',()=>{const on=document.body.classList.toggle('large');$('#fontToggle').setAttribute('aria-pressed',String(on));});
document.addEventListener('submit',()=>setTimeout(()=>{if(identity()!==owner){load();render();}},0));
window.addEventListener('storage',ev=>{if(ev.key==='mediainfolab_student_access_v1'){load();render();}});
})();
